import { create_list_edit_territories } from "@/graphql/mutations.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    createTerritoryDialog: Boolean
  },
  mixins: [get_all_org_users],
  data() {
    return {
      loading: false,
      loading1: false,
      territoryName: "",
      searchF: "",
      territoryCity: "",
      territoryDescription: "",
      terriotoryManager: "",
      userArray: [],
      countryData: "India",
      // Default to India, not shown in UI
      locationPincode: "",
      locationState: "",
      locationDistrict: "",
      districtItems: [],
      stateItems: [],
      pincodeList: [],
      editingPincodeIndex: -1
    };
  },
  watch: {
    createTerritoryDialog: {
      async handler() {
        if (this.createTerritoryDialog == true) {
          this.$store.commit("Setnamesearch", "");
          await this.get_all_org_users();
          this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_details() {
      // Clear the array first to prevent duplicates
      this.userArray = [];
      const seenUserIds = new Set();
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && !seenUserIds.has(element.user_id)) {
          seenUserIds.add(element.user_id);
          this.userArray.push({
            title: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
      this.resetPincodeFields();
      this.pincodeList = [];
    },
    resetPincodeFields() {
      this.locationPincode = "";
      this.locationState = "";
      this.locationDistrict = "";
      this.districtItems = [];
      this.stateItems = [];
      this.editingPincodeIndex = -1;
    },
    is_Number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57)) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    async fetchPinData() {
      if (!this.locationPincode || this.locationPincode.length !== 6) {
        this.$emit("errorMsg", "Please enter a valid 6-digit Postal Index Number");
        return;
      }
      this.stateItems = [];
      this.districtItems = [];
      this.loading1 = true;
      try {
        const response = await fetch(`https://api.postalpincode.in/pincode/${this.locationPincode}`);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        if (!data || !data[0] || data[0].Status !== "Success") {
          throw new Error("Invalid pincode or no data found");
        }
        var masterArray = data[0].PostOffice;
        if (!masterArray || masterArray.length === 0) {
          throw new Error("No post office data found for this pincode");
        }

        // Deduplicate districts and states
        this.districtItems = [...new Set(masterArray.map(element => element.District))];
        this.stateItems = [...new Set(masterArray.map(element => element.State))];
        this.locationDistrict = data[0].PostOffice[0].District;
        this.locationState = data[0].PostOffice[0].State;
      } catch (err) {
        console.error("Error fetching pincode data:", err);
        this.$emit("errorMsg", err.message || "Failed to fetch pincode data");
        this.locationPincode = "";
        this.locationDistrict = "";
        this.locationState = "";
      } finally {
        this.loading1 = false;
      }
    },
    addPincodeToList() {
      if (!this.locationPincode || !this.locationState || !this.locationDistrict) {
        this.$emit("errorMsg", "Please fill all pincode fields");
        return;
      }

      // Check if pincode already exists
      const exists = this.pincodeList.some(item => item.pincode === this.locationPincode);
      if (exists && this.editingPincodeIndex === -1) {
        this.$emit("errorMsg", "This pincode is already in the list");
        return;
      }
      const pincodeData = {
        pincode: this.locationPincode,
        state: this.locationState,
        district: this.locationDistrict
      };
      if (this.editingPincodeIndex >= 0) {
        // Update existing pincode
        this.pincodeList[this.editingPincodeIndex] = pincodeData;
        this.editingPincodeIndex = -1;
      } else {
        // Add new pincode
        this.pincodeList.push(pincodeData);
      }
      this.resetPincodeFields();
    },
    editPincode(index) {
      const item = this.pincodeList[index];
      this.locationPincode = item.pincode;
      this.locationState = item.state;
      this.locationDistrict = item.district;
      this.editingPincodeIndex = index;
    },
    removePincode(index) {
      this.pincodeList.splice(index, 1);
      if (this.editingPincodeIndex === index) {
        this.resetPincodeFields();
      }
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_territories, {
          input: {
            action_type: "CREATE",
            territory_name: this.territoryName,
            territory_head: this.terriotoryManager.user_id,
            territory_head_name: this.terriotoryManager.title,
            organization_id: data.organization.organization_id,
            territory_description: this.territoryDescription,
            territory_states: this.pincodeList.length > 0 ? JSON.stringify(this.pincodeList) : null
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_edit_territories);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.resetValidation();
          this.$refs.form.reset();
          this.resetPincodeFields();
          this.pincodeList = [];
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
